inp = G['Demo pair 1 input']
out = G['Demo pair 1 output']

h, w = len(inp), len(inp[0])

# Check for each changed cell whether there's line-of-sight to an initial 3 in same row or col
def has_line_of_sight_to_3(i, j, inp_grid):
    """Check if cell (i,j) has unblocked path to any initial 3 in same row or column"""
    # Find initial 3 positions
    initial_3s = [(r,c) for r in range(h) for c in range(w) if inp_grid[r][c] == 3]

    # Check same row
    for i_3, j_3 in initial_3s:
        if i_3 == i:
            # Check left
            min_j = min(j, j_3)
            for cj in range(min_j, max(j, j_3)):
                if inp_grid[i][cj] != 0:  # Blocked by non-zero
                    break
            else:
                return True  # Path clear in row
            # Check right
            max_j = max(j, j_3)
            for cj in range(min(j, j_3), max_j):
                if inp_grid[i][cj] != 0:
                    break
            else:
                return True

    # Check same column
    for i_3, j_3 in initial_3s:
        if j_3 == j:
            min_i = min(i, i_3)
            for ri in range(min_i, max(i, i_3)):
                if inp_grid[ri][j] != 0:
                    break
            else:
                return True
            max_i = max(i, i_3)
            for ri in range(min(i, i_3), max_i):
                if inp_grid[ri][j] != 0:
                    break
            else:
                return True

    return False

changed_cells = [(i,j) for i in range(h) for j in range(w) if inp[i][j] != out[i][j]]
print('Checking line-of-sight hypothesis:')
all_match = True
for i, j in sorted(changed_cells):
    result = inp[i][j]
    predicted = has_line_of_sight_to_3(i, j, inp)
    matches = (result == 3) == predicted
    if not matches:
        print(f'MISMATCH at ({i},{j}): inp={inp[i][j]}, expected_has_los={predicted}, actual_out={out[i][j]}')
        all_match = False

if all_match:
    print('ALL CHANGED CELLS HAVE LINE-OF-SIGHT TO A 3')

# Also check that unchanged cells (that were 0) don't have line of sight
unchanged_zeros = [(i,j) for i in range(h) for j in range(w) if inp[i][j] == 0 and out[i][j] == 0]
none_have_los = True
for i, j in unchanged_zeros:
