def solve_simple_enclosed(matrix, fill_val):
    """Fill only completely enclosed 0-regions"""
    rows, cols = len(matrix), len(matrix[0])

    # Mark all 0-cells reachable from grid edge
    edge_reachable = set()
    stack = []

    for r in range(rows):
        for c in range(cols):
            if matrix[r][c] == 0 and (r == 0 or r == rows-1 or c == 0 or c == cols-1):
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
