    """Fill horizontal segments of 0s that are bounded by non-zero values (or edges)"""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    for r in range(h):
        i = 0
        while i < w:
            if grid[r][i] == 0:
                # Start of a segment
                start = i
                # Find end
                while i < w and grid[r][i] == 0:
                    i += 1
                end = i  # Exclusive

                # Check if it's bounded by non-zeros (left bound exists and right bound exists)
                left_bounded = (start > 0 and grid[r][start-1] != 0)
                right_bounded = (end < w and grid[r][end] != 0)

                if left_bounded and right_bounded:
                    # Fill the segment
                    for c in range(start, end):
