# Check connectivity patterns more carefully
# What if 4s act as walls but we can traverse diagonally around them?

def bfs_with_diagonal_avoidance(grid, start_cells, block_4=False):
    """BFS where we can move diagonally but might need to pass through adjacent wall"""
    visited = set(start_cells)
    dist = {s: 0 for s in start_cells}

    queue = deque([c for c in start_cells])
    while queue:
        ci, cj = queue.popleft()

        # Diagonal moves
        for di, dj in [(-1,-1),(-1,1),(1,-1),(1,1)]:
            ni, nj = ci + di, cj + dj
            if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]):
                cell_val = grid[ni][nj]
                # Allow diagonal move even through walls if corner is free
                if cell_val in [0, 3]:
                    if (ni,nj) not in visited:
                        visited.add((ni,nj))
                        dist[(ni,nj)] = dist[(ci,cj)] + 1
                        queue.append((ni,nj))
                elif cell_val == 4:
                    # Diagonally through a 4 requires checking if both orthogonal neighbors are clear
                    orthogonal_clear = (grid[ci][nj] != 4) and (grid[ni][cj] != 4)
                    if orthogonal_clear and (ni,nj) not in visited:
                        visited.add((ni,nj))
                        dist[(ni,nj)] = dist[(ci,cj)] + 1
                        queue.append((ni,nj))
        # Orthogonal moves (always allowed through 0s)
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = ci + di, cj + dj
            if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]):
